final class ObfuscatedTO(val id: String) {
  private val plain = scala.collection.mutable.Map.empty[String, String]
  private val protectedPairs = scala.collection.mutable.Map.empty[String, String]
  private var sealedMap: SealedObject = null                     // JCE

  def seal(cipher: Cipher): Unit = {
    val asJava = new java.util.HashMap[String, String]()
    protectedPairs.foreach { case (k, v) => asJava.put(k, v) }
    sealedMap = new SealedObject(asJava, cipher)
    protectedPairs.clear()                                       // drop the plaintext copy
  }
  override def toString: String = s"ObfuscatedTO($id)"           // not the protected map
}
